insert into public.questions (type, difficulty, prompt, verse_text, reference, translation, options, correct_index) values
  ('guess_the_book', 'easy', 'Which book of the Bible is this verse from?', 'In the beginning, God created heaven and earth.', 'Genesis 1:1', 'CPDV', array['Genesis', 'Exodus', 'Job', 'Psalms'], 0),
  ('guess_the_book', 'easy', 'Which book of the Bible is this verse from?', 'In the beginning was the Word, and the Word was with God, and God was the Word.', 'John 1:1', 'CPDV', array['Luke', 'John', 'Hebrews', 'Revelation'], 1),
  ('guess_the_book', 'easy', 'Which book of the Bible is this verse from?', 'Everything is possible in him who has strengthened me.', 'Philippians 4:13', 'CPDV', array['Ephesians', 'Galatians', 'Philippians', 'Colossians'], 2),
  ('guess_the_book', 'easy', 'Which book of the Bible is this verse from?', 'Therefore, you shall pray in this way: Our Father, who is in heaven: May your name be kept holy.', 'Matthew 6:9', 'CPDV', array['Mark', 'Luke', 'John', 'Matthew'], 3),
  ('guess_the_book', 'easy', 'Which book of the Bible is this verse from?', 'And God will wipe away every tear from their eyes. And death shall be no more. And neither mourning, nor crying out, nor grief shall be anymore. For the first things have passed away.”', 'Revelation 21:4', 'CPDV', array['Revelation', 'Isaiah', 'Daniel', 'Ezekiel'], 0),
  ('guess_the_book', 'easy', 'Which book of the Bible is this verse from?', 'And we know that, for those who love God, all things work together unto good, for those who, in accordance with his purpose, are called to be saints.', 'Romans 8:28', 'CPDV', array['Hebrews', 'Romans', 'James', '1 John'], 1),
  ('guess_the_book', 'easy', 'Which book of the Bible is this verse from?', 'But for now, these three continue: faith, hope, and charity. And the greatest of these is charity.', '1 Corinthians 13:13', 'CPDV', array['Romans', 'Galatians', '1 Corinthians', 'Ephesians'], 2),
  ('fill_in_the_blank', 'easy', 'Which word completes the verse?', 'The Lord directs me, and nothing will be ______ to me.', 'Psalm 22 (23):1', 'CPDV', array['wanting', 'denied', 'hidden', 'lacking'], 3),
  ('fill_in_the_blank', 'easy', 'Which word completes the verse?', 'Your word is a ______ to my feet and a light to my paths.', 'Psalm 118 (119):105', 'CPDV', array['lamp', 'torch', 'guide', 'shield'], 0),
  ('fill_in_the_blank', 'easy', 'Which word completes the verse?', 'Jesus said to him: “I am the Way, and the ______, and the Life. No one comes to the Father, except through me.', 'John 14:6', 'CPDV', array['Light', 'Truth', 'Word', 'Door'], 1),
  ('fill_in_the_blank', 'easy', 'Which word completes the verse?', 'Have confidence in the Lord with all your heart, and do not depend upon your own ______.', 'Proverbs 3:5', 'CPDV', array['wisdom', 'strength', 'prudence', 'counsel'], 2),
  ('fill_in_the_blank', 'easy', 'Which word completes the verse?', 'Blessed are the ______, for they shall be called sons of God.', 'Matthew 5:9', 'CPDV', array['meek', 'merciful', 'pure of heart', 'peacemakers'], 3),
  ('fill_in_the_blank', 'easy', 'Which word completes the verse?', 'And God said, “Let there be light.” And light ______.', 'Genesis 1:3', 'CPDV', array['became', 'was', 'appeared', 'remained'], 0),
  ('fill_in_the_blank', 'easy', 'Which word completes the verse?', 'But those who hope in the Lord will renew their strength. They will take up wings like ______. They will run and not struggle. They will walk and not tire.', 'Isaiah 40:31', 'CPDV', array['doves', 'eagles', 'hawks', 'angels'], 1),
  ('who_said_it', 'easy', 'Who spoke these words?', 'No one has a greater love than this: that he lay down his life for his friends.', 'John 15:13', 'CPDV', array['Peter', 'Paul', 'Jesus', 'John'], 2),
  ('who_said_it', 'easy', 'Who spoke these words?', 'Come to me, all you who labor and have been burdened, and I will refresh you.', 'Matthew 11:28', 'CPDV', array['John the Baptist', 'Isaiah', 'Paul', 'Jesus'], 3),
  ('who_said_it', 'easy', 'Who spoke these words?', 'She answered, “Do not be against me, as if I would abandon you and go away; for wherever you will go, I will go, and where you will stay, I also will stay with you. Your people are my people, and your God is my God.', 'Ruth 1:16', 'CPDV', array['Ruth', 'Naomi', 'Esther', 'Hannah'], 0),
  ('who_said_it', 'easy', 'Who spoke these words?', 'I have fought the good fight. I have completed the course. I have preserved the faith.', '2 Timothy 4:7', 'CPDV', array['Peter', 'Paul', 'James', 'Timothy'], 1),
  ('who_said_it', 'easy', 'Who spoke these words?', 'For I know that my Redeemer lives, and on the last day I will rise out of the earth.', 'Job 19:25', 'CPDV', array['David', 'Isaiah', 'Job', 'Jeremiah'], 2),
  ('who_said_it', 'easy', 'Who spoke these words?', 'You shall not have strange gods before me.', 'Exodus 20:3', 'CPDV', array['Moses', 'Aaron', 'Joshua', 'God'], 3),
  ('guess_the_book', 'medium', 'Which book of the Bible is this verse from?', 'All things have their time, and all things under heaven continue during their interval.', 'Ecclesiastes 3:1', 'CPDV', array['Ecclesiastes', 'Proverbs', 'Job', 'Song of Songs'], 0),
  ('guess_the_book', 'medium', 'Which book of the Bible is this verse from?', 'For I know the thoughts that I think over you, says the Lord: thoughts of peace and not of affliction, so that I may give you patience and an end.', 'Jeremiah 29:11', 'CPDV', array['Isaiah', 'Jeremiah', 'Ezekiel', 'Daniel'], 1),
  ('guess_the_book', 'medium', 'Which book of the Bible is this verse from?', 'I will reveal to you, O man, what is good, and what the Lord requires from you, and how to act with judgment, and to love mercy, and to walk carefully with your God.', 'Micah 6:8', 'CPDV', array['Hosea', 'Amos', 'Micah', 'Zechariah'], 2),
  ('guess_the_book', 'medium', 'Which book of the Bible is this verse from?', 'Now, faith is the substance of things hoped for, the evidence of things not apparent.', 'Hebrews 11:1', 'CPDV', array['Romans', 'James', '1 Peter', 'Hebrews'], 3),
  ('guess_the_book', 'medium', 'Which book of the Bible is this verse from?', 'Thus even faith, if it does not have works, is dead, in and of itself.', 'James 2:17', 'CPDV', array['James', '1 John', 'Titus', 'Jude'], 0),
  ('guess_the_book', 'medium', 'Which book of the Bible is this verse from?', 'And I will give to you a new heart, and I will place in you a new spirit. And I will take away the heart of stone from your body, and I will give to you a heart of flesh.', 'Ezekiel 36:26', 'CPDV', array['Jeremiah', 'Ezekiel', 'Isaiah', 'Joel'], 1),
  ('guess_the_book', 'medium', 'Which book of the Bible is this verse from?', 'But the fruit of the Spirit is charity, joy, peace, patience, kindness, goodness, forbearance,', 'Galatians 5:22', 'CPDV', array['Ephesians', 'Colossians', 'Galatians', 'Philippians'], 2),
  ('guess_the_book', 'medium', 'Which book of the Bible is this verse from?', 'Cast all your cares upon him, for he takes care of you.', '1 Peter 5:7', 'CPDV', array['2 Peter', '1 John', 'James', '1 Peter'], 3),
  ('guess_the_book', 'medium', 'Which book of the Bible is this verse from?', 'For unto us a child is born, and unto us a son is given. And leadership is placed upon his shoulder. And his name shall be called: wonderful Counselor, mighty God, father of the future age, Prince of Peace.', 'Isaiah 9:6', 'CPDV', array['Isaiah', 'Micah', 'Jeremiah', 'Psalms'], 0),
  ('fill_in_the_blank', 'medium', 'Which word completes the verse?', 'For the ______ of sin is death. But the free gift of God is eternal life in Christ Jesus our Lord.', 'Romans 6:23', 'CPDV', array['price', 'wages', 'cost', 'reward'], 1),
  ('fill_in_the_blank', 'medium', 'Which word completes the verse?', 'They said to him, “Caesar’s.” Then he said to them, “Then ______ to Caesar what is of Caesar; and to God what is of God.”', 'Matthew 22:21', 'CPDV', array['give', 'return', 'render', 'restore'], 2),
  ('fill_in_the_blank', 'medium', 'Which word completes the verse?', 'You shall love the Lord your God with all your heart, and with all your soul, and with all your ______.', 'Deuteronomy 6:5', 'CPDV', array['mind', 'might', 'being', 'strength'], 3),
  ('fill_in_the_blank', 'medium', 'Which word completes the verse?', 'And after the earthquake, there was a fire. But the Lord was not in the fire. And after the fire, there was the whisper of a ______.', '1 Kings 19:12', 'CPDV', array['gentle breeze', 'rushing wind', 'quiet whisper', 'distant thunder'], 0),
  ('fill_in_the_blank', 'medium', 'Which word completes the verse?', 'Create a clean heart in me, O God. And renew an ______ spirit within my inmost being.', 'Psalm 50 (51):12', 'CPDV', array['steadfast', 'upright', 'humble', 'willing'], 1),
  ('fill_in_the_blank', 'medium', 'Which word completes the verse?', 'For I desired ______ and not sacrifice, and knowledge of God more than holocausts.', 'Hosea 6:6', 'CPDV', array['justice', 'kindness', 'mercy', 'obedience'], 2),
  ('fill_in_the_blank', 'medium', 'Which word completes the verse?', 'Rejoice well, daughter of Zion, shout for joy, daughter of Jerusalem. Behold, your King will come to you: the Just One, the Savior. He is poor and riding upon a donkey, and upon a ______, the son of a donkey.', 'Zechariah 9:9', 'CPDV', array['foal', 'lamb', 'mule', 'colt'], 3),
  ('fill_in_the_blank', 'medium', 'Which word completes the verse?', 'The Lord God is my strength. And he will set my feet like those of the ______. And he, the victor, will lead me beyond my high places while singing psalms.', 'Habakkuk 3:19', 'CPDV', array['stag', 'eagle', 'lion', 'ram'], 0),
  ('who_said_it', 'medium', 'Who spoke these words?', 'And I heard the voice of the Lord, saying: “Whom shall I send?” and, “Who will go for us?” And I said: “Here I am. Send me.”', 'Isaiah 6:8', 'CPDV', array['Moses', 'Isaiah', 'Jeremiah', 'Samuel'], 1),
  ('who_said_it', 'medium', 'Who spoke these words?', 'Whatever you do, do it from the heart, as for the Lord, and not for men.', 'Colossians 3:23', 'CPDV', array['Peter', 'James', 'Paul', 'John'], 2),
  ('who_said_it', 'medium', 'Who spoke these words?', 'And in response he said, “It has been written: ‘Not by bread alone shall man live, but by every word that proceeds from the mouth of God.’ ”', 'Matthew 4:4', 'CPDV', array['Moses', 'Paul', 'John the Baptist', 'Jesus'], 3),
  ('who_said_it', 'medium', 'Who spoke these words?', 'And continuing on a little further, he fell prostrate on his face, praying and saying: “My Father, if it is possible, let this chalice pass away from me. Yet truly, let it not be as I will, but as you will.”', 'Matthew 26:39', 'CPDV', array['Jesus', 'Peter', 'Stephen', 'Paul'], 0),
  ('who_said_it', 'medium', 'Who spoke these words?', 'Therefore, give to your servant a teachable heart, so that he may be able to judge your people, and to discern between good and evil. For who will be able to judge this people, your people, who are so many?”', '1 Kings 3:9', 'CPDV', array['David', 'Solomon', 'Samuel', 'Nathan'], 1),
  ('who_said_it', 'medium', 'Who spoke these words?', 'and he said, “Naked I departed from my mother’s womb, and naked I shall return. The Lord gave, and the Lord has taken away. Just as it pleased the Lord, so has it been done. Blessed be the name of the Lord.”', 'Job 1:21', 'CPDV', array['David', 'Jeremiah', 'Job', 'Tobit'], 2),
  ('who_said_it', 'medium', 'Who spoke these words?', 'Act manfully and be strengthened. Do not be afraid, and do not dread at the sight of them. For the Lord your God himself is your commander, and he will neither dismiss nor abandon you.”', 'Deuteronomy 31:6', 'CPDV', array['Joshua', 'Caleb', 'Aaron', 'Moses'], 3),
  ('who_said_it', 'medium', 'Who spoke these words?', 'My God has sent his angel, and he has closed the mouths of the lions, and they have not harmed me, because before him justice has been found in me, and, even before you, O king, I have committed no offense.”', 'Daniel 6:22', 'CPDV', array['Daniel', 'Shadrach', 'Ezekiel', 'Jeremiah'], 0),
  ('guess_the_book', 'hard', 'Which book of the Bible is this verse from?', 'A faithful friend is a strong shelter, and whoever has found one has found a treasure.', 'Sirach 6:14', 'CPDV', array['Sirach', 'Proverbs', 'Wisdom', 'Ecclesiastes'], 0),
  ('guess_the_book', 'hard', 'Which book of the Bible is this verse from?', 'But the souls of the just are in the hand of God and no torment of death will touch them.', 'Wisdom 3:1', 'CPDV', array['Sirach', 'Wisdom', 'Job', 'Psalms'], 1),
  ('guess_the_book', 'hard', 'Which book of the Bible is this verse from?', 'For you scourge, and you save. You lead down to the grave, and you bring up again. And there is no one who can escape from your hand.', 'Tobit 13:2', 'CPDV', array['Judith', 'Daniel', 'Tobit', 'Baruch'], 2),
  ('guess_the_book', 'hard', 'Which book of the Bible is this verse from?', 'Therefore, it is a holy and beneficial thought to pray on behalf of those who have passed away, so that they may be released from sins.', '2 Maccabees 12:46', 'CPDV', array['1 Maccabees', 'Sirach', 'Wisdom', '2 Maccabees'], 3),
  ('guess_the_book', 'hard', 'Which book of the Bible is this verse from?', 'Learn where prudence is, where virtue is, where understanding is, so that you may know at the same time where long life and prosperity are, where the light of the eyes and peace are.', 'Baruch 3:14', 'CPDV', array['Baruch', 'Jeremiah', 'Lamentations', 'Wisdom'], 0),
  ('guess_the_book', 'hard', 'Which book of the Bible is this verse from?', 'For your power, O Lord, is not in numbers, nor is your will with the strength of horses, nor from the beginning have the arrogant been pleasing to you. But the pleas of the humble and the meek have always pleased you.', 'Judith 9:16', 'CPDV', array['Esther', 'Judith', 'Ruth', 'Tobit'], 1),
  ('guess_the_book', 'hard', 'Which book of the Bible is this verse from?', 'And Judas, and his brothers, and all the assembly of Israel decreed that the day of the dedication of the altar must be kept in its time, from year to year, for eight days, from the twenty-fifth day of the month of Kislev, with joy and gladness.', '1 Maccabees 4:59', 'CPDV', array['Nehemiah', 'Ezra', '1 Maccabees', '2 Maccabees'], 2),
  ('guess_the_book', 'hard', 'Which book of the Bible is this verse from?', 'Behold, he who is unbelieving, his soul will not be right within himself; but he who is just shall live in his faith.', 'Habakkuk 2:4', 'CPDV', array['Nahum', 'Zephaniah', 'Haggai', 'Habakkuk'], 3),
  ('guess_the_book', 'hard', 'Which book of the Bible is this verse from?', 'The Lord is good, and a comforter in the day of tribulation, and he knows those who hope in him.', 'Nahum 1:7', 'CPDV', array['Nahum', 'Micah', 'Joel', 'Obadiah'], 0),
  ('guess_the_book', 'hard', 'Which book of the Bible is this verse from?', 'But those who have taught will shine like the brightness of the firmament, and those who instruct many towards justice, like the stars for unending eternity.', 'Daniel 12:3', 'CPDV', array['Ezekiel', 'Daniel', 'Isaiah', 'Malachi'], 1),
  ('guess_the_book', 'hard', 'Which book of the Bible is this verse from?', 'Confess to the Lord, for he is good. For his mercy is eternal.', '1 Chronicles 16:34', 'CPDV', array['1 Kings', '2 Kings', '1 Chronicles', '2 Chronicles'], 2),
  ('fill_in_the_blank', 'hard', 'Which word completes the verse?', 'The fear of the Lord is the beginning of ______, and was created with the faithful in the womb, and walks with elect women, and is known by the just and the faithful.', 'Sirach 1:16', 'CPDV', array['knowledge', 'justice', 'life', 'wisdom'], 3),
  ('fill_in_the_blank', 'hard', 'Which word completes the verse?', 'For God created man to be ______, and he made him in the image of his own likeness.', 'Wisdom 2:23', 'CPDV', array['immortal', 'upright', 'holy', 'free'], 0),
  ('fill_in_the_blank', 'hard', 'Which word completes the verse?', 'Whatever you would ______ to have done to you by another, see that you never do so to another.', 'Tobit 4:16', 'CPDV', array['fear', 'hate', 'refuse', 'dread'], 1),
  ('fill_in_the_blank', 'hard', 'Which word completes the verse?', 'For victory in warfare is not in the ______ of the army, but in the strength from heaven.', '1 Maccabees 3:19', 'CPDV', array['courage', 'discipline', 'multitude', 'number'], 2),
  ('fill_in_the_blank', 'hard', 'Which word completes the verse?', 'Indeed, she is the brightness of eternal light, and the unspotted ______ of the majesty of God, and the image of his goodness.', 'Wisdom 7:26', 'CPDV', array['image', 'likeness', 'seal', 'mirror'], 3),
  ('fill_in_the_blank', 'hard', 'Which word completes the verse?', 'But he himself was wounded because of our iniquities. He was bruised because of our wickedness. The discipline of our peace was upon him. And by his ______, we are healed.', 'Isaiah 53:5', 'CPDV', array['wounds', 'stripes', 'sorrows', 'chains'], 0),
  ('fill_in_the_blank', 'hard', 'Which word completes the verse?', '“Before I formed you in the womb, I knew you. And before you went forth from the womb, I sanctified you. And I made you a ______ to the nations.”', 'Jeremiah 1:5', 'CPDV', array['light', 'prophet', 'sign', 'witness'], 1),
  ('fill_in_the_blank', 'hard', 'Which word completes the verse?', 'And rend your hearts, and not your ______, and convert to the Lord your God. For he is gracious and merciful, patient and full of compassion, and steadfast despite ill will.', 'Joel 2:13', 'CPDV', array['robes', 'tents', 'garments', 'veils'], 2),
  ('fill_in_the_blank', 'hard', 'Which word completes the verse?', 'O Adonai, O Lord, you are great, and ______ is in your virtue, and no one is able to overcome you.', 'Judith 16:16', 'CPDV', array['glory', 'majesty', 'power', 'splendor'], 3),
  ('fill_in_the_blank', 'hard', 'Which word completes the verse?', 'And if anyone loves justice, her labors hold great virtues; for she teaches ______ and prudence, justice and virtue, and nothing is more useful in human life.', 'Wisdom 8:7', 'CPDV', array['temperance', 'patience', 'humility', 'mercy'], 0),
  ('who_said_it', 'hard', 'Who spoke these words?', 'And when he had reached his last breath, he spoke in this way: “You, indeed, O most wicked man, are destroying us in this present life. But the King of the world will raise us up, in eternal life at the resurrection, for we die on behalf of his laws.”', '2 Maccabees 7:9', 'CPDV', array['Eleazar', 'One of the seven brothers', 'Judas Maccabeus', 'Mattathias'], 1),
  ('who_said_it', 'hard', 'Who spoke these words?', 'And he said to them: “Go, eat fat foods and drink sweet drinks, and send portions to those who have not prepared for themselves. For it is the holy day of the Lord. And do not be sad. For the joy of the Lord is also our strength.”', 'Nehemiah 8:10', 'CPDV', array['Ezra', 'Zerubbabel', 'Nehemiah', 'Cyrus'], 2),
  ('who_said_it', 'hard', 'Who spoke these words?', 'And falling to the ground, he heard a voice saying to him, “Saul, Saul, why are you persecuting me?”', 'Acts 9:4', 'CPDV', array['Stephen', 'Ananias', 'Gabriel', 'Jesus'], 3),
  ('who_said_it', 'hard', 'Who spoke these words?', 'For it is good to conceal the secret of a king, just as it is also honorable to reveal and to confess the works of God.', 'Tobit 12:7', 'CPDV', array['The Angel Raphael', 'Tobit', 'Tobias', 'Sarah'], 0),
  ('who_said_it', 'hard', 'Who spoke these words?', 'May God be forgiving to us. It is not useful for us to abandon the law and the justices of God.', '1 Maccabees 2:21', 'CPDV', array['Judas Maccabeus', 'Mattathias', 'Simon', 'Jonathan'], 1),
  ('who_said_it', 'hard', 'Who spoke these words?', 'But the second is similar to it: ‘You shall love your neighbor as yourself.’ There is no other commandment greater than these.”', 'Mark 12:31', 'CPDV', array['Moses', 'Paul', 'Jesus', 'Peter'], 2),
  ('who_said_it', 'hard', 'Who spoke these words?', 'The Lord will fight on your behalf, and you will remain silent.”', 'Exodus 14:14', 'CPDV', array['Aaron', 'Joshua', 'Miriam', 'Moses'], 3),
  ('who_said_it', 'hard', 'Who spoke these words?', 'Behold, I am instructing you. Be strengthened, and be steadfast. Do not dread, and do not fear. For the Lord your God is with you in all things, wherever you may go.”', 'Joshua 1:9', 'CPDV', array['The Lord', 'Moses', 'Caleb', 'Eleazar'], 0),
  ('who_said_it', 'hard', 'Who spoke these words?', '“O death, where is your victory? O death, where is your sting?”', '1 Corinthians 15:55', 'CPDV', array['Peter', 'Paul', 'John', 'James'], 1),
  ('guess_the_book', 'easy', 'Which book of the Bible is this verse from?', 'For God so loved the world that he gave his only-begotten Son, so that all who believe in him may not perish, but may have eternal life.', 'John 3:16', 'CPDV', array['Matthew', 'Luke', 'John', 'Romans'], 2),
  ('guess_the_book', 'easy', 'Which book of the Bible is this verse from?', 'Therefore, go forth and teach all nations, baptizing them in the name of the Father and of the Son and of the Holy Spirit,', 'Matthew 28:19', 'CPDV', array['Matthew', 'Mark', 'Acts', 'Luke'], 0),
  ('guess_the_book', 'easy', 'Which book of the Bible is this verse from?', 'And upon entering, the Angel said to her: “Hail, full of grace. The Lord is with you. Blessed are you among women.”', 'Luke 1:28', 'CPDV', array['Matthew', 'Luke', 'John', 'Mark'], 1),
  ('guess_the_book', 'easy', 'Which book of the Bible is this verse from?', 'God said to Moses, “I AM WHO AM.” He said: “Thus shall you say to the sons of Israel: ‘HE WHO IS has sent me to you.’ ”', 'Exodus 3:14', 'CPDV', array['Genesis', 'Numbers', 'Deuteronomy', 'Exodus'], 3),
  ('guess_the_book', 'easy', 'Which book of the Bible is this verse from?', 'For this reason, the Lord himself will grant to you a sign. Behold, a virgin will conceive, and she will give birth to a son, and his name will be called Immanuel.', 'Isaiah 7:14', 'CPDV', array['Isaiah', 'Jeremiah', 'Micah', 'Ezekiel'], 0),
  ('guess_the_book', 'easy', 'Which book of the Bible is this verse from?', 'Whoever does not love, does not know God. For God is love.', '1 John 4:8', 'CPDV', array['Romans', '1 John', 'James', '1 Peter'], 1),
  ('guess_the_book', 'easy', 'Which book of the Bible is this verse from?', 'Be empty, and see that I am God. I will be exalted among the peoples, and I will be exalted upon the earth.', 'Psalm 45 (46):11', 'CPDV', array['Proverbs', 'Job', 'Psalms', 'Isaiah'], 2),
  ('fill_in_the_blank', 'easy', 'Which word completes the verse?', 'Blessed are the ______ in spirit, for theirs is the kingdom of heaven.', 'Matthew 5:3', 'CPDV', array['meek', 'humble', 'poor', 'pure'], 2),
  ('fill_in_the_blank', 'easy', 'Which word completes the verse?', 'And Jesus ______.', 'John 11:35', 'CPDV', array['prayed', 'wept', 'slept', 'spoke'], 1),
  ('fill_in_the_blank', 'easy', 'Which word completes the verse?', 'Ask, and it shall be given to you. Seek, and you shall find. ______, and it shall be opened to you.', 'Matthew 7:7', 'CPDV', array['Call', 'Wait', 'Cry', 'Knock'], 3),
  ('fill_in_the_blank', 'easy', 'Which word completes the verse?', 'This is the day that the Lord has made. Let us exult and ______ in it.', 'Psalm 117 (118):24', 'CPDV', array['sing', 'pray', 'give thanks', 'rejoice'], 3),
  ('fill_in_the_blank', 'easy', 'Which word completes the verse?', 'Then Mary said: “Behold, I am the ______ of the Lord. Let it be done to me according to your word.” And the Angel departed from her.', 'Luke 1:38', 'CPDV', array['servant', 'daughter', 'handmaid', 'child'], 2),
  ('fill_in_the_blank', 'easy', 'Which word completes the verse?', 'Pray without ______.', '1 Thessalonians 5:17', 'CPDV', array['ceasing', 'fear', 'doubt', 'tiring'], 0),
  ('fill_in_the_blank', 'easy', 'Which word completes the verse?', 'The fear of the Lord is the ______ of wisdom, and knowledge of holiness is prudence.', 'Proverbs 9:10', 'CPDV', array['end', 'beginning', 'root', 'crown'], 1),
  ('who_said_it', 'easy', 'Who spoke these words?', 'My soul magnifies the Lord.', 'Luke 1:46', 'CPDV', array['Elizabeth', 'Hannah', 'Mary', 'Anna'], 2),
  ('who_said_it', 'easy', 'Who spoke these words?', 'You are the Christ, the Son of the living God.”', 'Matthew 16:16', 'CPDV', array['Peter', 'John', 'Andrew', 'Thomas'], 0),
  ('who_said_it', 'easy', 'Who spoke these words?', 'I am the Resurrection and the Life. Whoever believes in me, even though he has died, he shall live.', 'John 11:25', 'CPDV', array['Paul', 'Peter', 'Martha', 'Jesus'], 3),
  ('who_said_it', 'easy', 'Who spoke these words?', 'Speak, Lord, for your servant is listening.”', '1 Samuel 3:10', 'CPDV', array['Eli', 'Samuel', 'Saul', 'David'], 1),
  ('who_said_it', 'easy', 'Who spoke these words?', 'My Lord and my God.”', 'John 20:28', 'CPDV', array['Peter', 'John', 'Thomas', 'Philip'], 2),
  ('who_said_it', 'easy', 'Who spoke these words?', 'Behold, the Lamb of God. Behold, he who takes away the sin of the world.', 'John 1:29', 'CPDV', array['John the Baptist', 'Peter', 'Andrew', 'Nathanael'], 0),
  ('guess_the_book', 'medium', 'Which book of the Bible is this verse from?', 'So if anyone is a new creature in Christ, what is old has passed away. Behold, all things have been made new.', '2 Corinthians 5:17', 'CPDV', array['Romans', '2 Corinthians', 'Galatians', 'Colossians'], 1),
